for _ in range(int(input())):
	(n, k) = map(int, input().split())
	l = list(map(int, input().split()))
	count = 0
	for i in l:
		if i % 2 == 0:
			count += 1
	if k == 0:
		if n - count == 0:
			print('NO')
		else:
			print('YES')
	elif count >= k:
		print('YES')
	else:
		print('NO')
